CREATE TRIGGER source_cursors_never_regress
BEFORE UPDATE OF value, kind ON source_cursors
WHEN NEW.value < OLD.value OR NEW.kind <> OLD.kind
BEGIN
  SELECT RAISE(ABORT, 'CURSOR_REGRESSION');
END;
CREATE TRIGGER deliveries_match_message
BEFORE INSERT ON deliveries
WHEN NOT EXISTS (
  SELECT 1 FROM messages m
   WHERE m.id = NEW.message_id
     AND m.dwarf_id = NEW.dwarf_id
     AND ((NEW.kind = 'answers-record') = (m.role = 'answers-record'))
     AND m.role IN ('person', 'answers-record')
)
BEGIN
  SELECT RAISE(ABORT, 'DELIVERY_MESSAGE_MISMATCH');
END;
CREATE TRIGGER deliveries_match_message_update
BEFORE UPDATE OF message_id, dwarf_id, kind ON deliveries
WHEN NEW.message_id <> OLD.message_id OR NEW.dwarf_id <> OLD.dwarf_id OR NEW.kind <> OLD.kind
BEGIN
  SELECT RAISE(ABORT, 'DELIVERY_MESSAGE_MISMATCH');
END;
CREATE TRIGGER ledger_entries_accumulate
AFTER INSERT ON ledger_entries
BEGIN
  INSERT INTO material_totals (mine_id, material, tokens, units)
  VALUES (NEW.mine_id, NEW.material, NEW.tokens, NEW.units)
  ON CONFLICT (mine_id, material) DO UPDATE
    SET tokens = tokens + excluded.tokens,
        units  = units + excluded.units;
END;
CREATE TRIGGER ledger_entries_withdraw
AFTER DELETE ON ledger_entries
BEGIN
  UPDATE material_totals
     SET tokens = tokens - OLD.tokens,
         units  = units - OLD.units
   WHERE mine_id = OLD.mine_id AND material = OLD.material;
END;
CREATE TRIGGER ledger_entries_immutable
BEFORE UPDATE ON ledger_entries
BEGIN
  SELECT RAISE(ABORT, 'LEDGER_ENTRY_IMMUTABLE');
END;
